/**
 * 课程专属图标组件
 *
 * 使用真实SVG图标替代emoji，提供更专业的视觉效果
 */

import React from 'react'

export interface CourseIconConfig {
  id: string
  name: string
  icon: React.ReactNode  // 使用React组件而不是emoji字符串
  color: string
  bgColor: string
  gradient: string
  description: string
}

