// 课程图标配置
export const COURSE_ICONS: Record<string, CourseIconConfig> = {
  c: {
    id: 'c',
    name: 'C语言程序设计',
    icon: <CIcon className="w-full h-full" />,
    color: 'text-blue-500',
    bgColor: 'bg-blue-500/10',
    gradient: 'from-blue-500 to-blue-600',
    description: '计算机程序设计基础，学习C语言核心概念',
  },
  cpp: {
    id: 'cpp',
    name: 'C++程序设计',
    icon: <CppIcon className="w-full h-full" />,
    color: 'text-indigo-500',
    bgColor: 'bg-indigo-500/10',
    gradient: 'from-indigo-500 to-indigo-600',
    description: '面向对象编程，C++高级特性',
  },
  python: {
    id: 'python',
    name: 'Python程序设计',
    icon: <PythonIcon className="w-full h-full" />,
    color: 'text-emerald-500',
    bgColor: 'bg-emerald-500/10',
    gradient: 'from-emerald-500 to-teal-500',
    description: 'Python编程从入门到精通',
  },
} as const

/**
 * 获取课程配置
 */
export function getCourseConfig(courseId: string): CourseIconConfig | undefined {
  return COURSE_ICONS[courseId]
}

/**
 * 获取课程颜色类名
 */
export function getCourseColor(courseId: string): string {
  return COURSE_ICONS[courseId]?.color ?? 'text-gray-500'
}

/**
 * 获取课程背景色类名
 */
export function getCourseBgColor(courseId: string): string {
  return COURSE_ICONS[courseId]?.bgColor ?? 'bg-gray-500/10'
}

/**
 * 获取课程渐变类名
 */
export function getCourseGradient(courseId: string): string {
  return COURSE_ICONS[courseId]?.gradient ?? 'from-gray-500 to-gray-600'
}

// 导出图标组件供直接使用
export {
  PythonIcon,
  RustIcon,
  CppIcon,
  CIcon,
  JavaIcon,
  DSAIcon,
  AlgorithmsIcon,
  DiscreteMathIcon,
}
